SELECT budget_bucket, total_budget FROM (SELECT CASE WHEN budget >= 3780000 THEN 'high' WHEN budget >= 1648000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget FROM departments GROUP BY CASE WHEN budget >= 3780000 THEN 'high' WHEN budget >= 1648000 THEN 'mid' ELSE 'low' END) AS agg WHERE total_budget < 23411000 ORDER BY total_budget DESC, budget_bucket LIMIT 50;
